9	/**
10	 * Runs after {@link NormalizeOwnerTelephone} on {@code POST /api/owners}: rejects the request
11	 * with 409 via {@link DuplicateTelephoneException} when the normalized telephone is already used
12	 * by any existing owner. Runs before {@link BuildOwner} so no owner is created on conflict.
13	 */
14	public class CheckUniqueOwnerTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateTelephoneException {
18	        String telephone = request.getTelephone();
19	        for (Owner existing : ownerRepository.findByTelephone(telephone)) {
20	            if (telephone.equals(existing.getTelephone())) {
21	                throw new DuplicateTelephoneException(telephone);
22	            }
23	        }
24	    }
25	}
