11	/**
12	 * Runs after {@link NormalizeOwnerEmail} on {@code POST /api/owners}: rejects the request with 409
13	 * via {@link DuplicateEmailException} when the normalized (lower-cased) email is already used by any
14	 * existing owner. Email is optional, so an absent (null or blank) email is never a conflict. Runs
15	 * before {@link BuildOwner} so no owner is created on conflict.
16	 */
17	public class CheckUniqueOwnerEmail {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateEmailException {
21	        String email = request.getEmail();
22	        if (email == null || email.isBlank()) {
23	            return;
24	        }
25	        String normalized = email.toLowerCase(Locale.ROOT);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            String other = existing.getEmail();
28	            if (other != null && normalized.equals(other.toLowerCase(Locale.ROOT))) {
29	                throw new DuplicateEmailException(normalized);
30	            }
31	        }
32	    }
33	}
