11	/**
12	 * Runs on {@code POST /api/owners} before {@link BuildOwner} (so no owner is created on conflict):
13	 * rejects the request with 409 via {@link DuplicateHouseholdException} when another owner already
14	 * has the same last name and the same address, compared case-insensitively with collapsed
15	 * whitespace. The check is skipped when the request opts in with {@code sharesHousehold} true,
16	 * letting several owners share one household.
17	 */
18	public class CheckUniqueOwnerHousehold {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DuplicateHouseholdException {
22	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return;
24	        }
25	        String lastName = normalizeName(request.getLastName());
26	        String address = OwnerAddressNormalizer.normalize(request.getAddress());
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (lastName.equals(normalizeName(existing.getLastName()))
29	                    && address.equals(OwnerAddressNormalizer.normalize(existing.getAddress()))) {
30	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
31	            }
32	        }
33	    }
34	
35	    /** Lower-case and collapse runs of whitespace so comparison is case- and whitespace-insensitive. */
36	    private static String normalizeName(String value) {
37	        if (value == null) {
38	            return "";
39	        }
40	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
41	    }
42	}
