3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Canonical address normalization applied whenever an owner is created. The rules are: trim the
8	 * ends, collapse every run of whitespace to a single space, upper-case, and expand a small set of
9	 * common street-type abbreviations to their full word ({@code ST -> STREET}, {@code RD -> ROAD},
10	 * {@code AVE -> AVENUE}). The result is what gets stored and returned, and it is the form every
11	 * address comparison (household duplicate detection and the shared household id) uses, so equal
12	 * addresses written differently collapse to the same value.
13	 */
14	final class OwnerAddressNormalizer {
15	
16	    private static final Map<String, String> ABBREVIATIONS = Map.of(
17	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
18	
19	    private OwnerAddressNormalizer() {
20	    }
21	
22	    /** Normalize an address; a null or whitespace-only value normalizes to the empty string. */
23	    static String normalize(String value) {
24	        if (value == null) {
25	            return "";
26	        }
27	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
28	        if (collapsed.isEmpty()) {
29	            return "";
30	        }
31	        String[] tokens = collapsed.split(" ");
32	        StringBuilder sb = new StringBuilder(collapsed.length());
33	        for (int i = 0; i < tokens.length; i++) {
34	            if (i > 0) {
35	                sb.append(' ');
36	            }
37	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
38	        }
39	        return sb.toString();
40	    }
41	}
