3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.repository.OwnerRepository;
14	
15	/**
16	 * Runs on {@code POST /api/owners} after {@link BuildOwner}, when the request opts in with
17	 * {@code sharesHousehold} true. When another owner already shares the household — same last name
18	 * and same address, compared case-insensitively with collapsed whitespace (the same comparison
19	 * {@link CheckUniqueOwnerHousehold} skips) — every member of that household is given one stable
20	 * shared {@code householdId}: an existing member's id is reused if present, otherwise a new id is
21	 * derived deterministically from the normalized last name and address (so independent joiners
22	 * compute the same value). The new owner and any member lacking an id are assigned it, and the
23	 * existing members are saved so the whole household shares the identifier. Without a matching
24	 * owner, or when {@code sharesHousehold} is not set, no household is formed and no id is assigned.
25	 */
26	public class AssignOwnerHousehold {
27	
28	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
29	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return;
31	        }
32	        String lastName = normalizeName(request.getLastName());
33	        String address = OwnerAddressNormalizer.normalize(request.getAddress());
34	        List<Owner> household = new ArrayList<>();
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (lastName.equals(normalizeName(existing.getLastName()))
37	                    && address.equals(OwnerAddressNormalizer.normalize(existing.getAddress()))) {
38	                household.add(existing);
39	            }
40	        }
41	        if (household.isEmpty()) {
42	            return;
43	        }
44	        String householdId = existingHouseholdId(household);
45	        if (householdId == null) {
46	            householdId = deriveHouseholdId(lastName, address);
47	        }
48	        owner.setHouseholdId(householdId);
49	        for (Owner member : household) {
50	            if (member.getHouseholdId() == null) {
51	                member.setHouseholdId(householdId);
52	                ownerRepository.save(member);
53	            }
54	        }
55	    }
56	
57	    /** Reuse an id already assigned to any household member, so late joiners keep the shared value. */
58	    private static String existingHouseholdId(List<Owner> household) {
59	        for (Owner member : household) {
60	            if (member.getHouseholdId() != null) {
61	                return member.getHouseholdId();
62	            }
63	        }
64	        return null;
65	    }
66	
67	    /** A stable 8-hex-character identifier derived from the normalized last name and address. */
68	    private static String deriveHouseholdId(String lastName, String address) {
69	        try {
70	            byte[] digest = MessageDigest.getInstance("SHA-256")
71	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
72	            StringBuilder sb = new StringBuilder();
73	            for (int i = 0; i < 4; i++) {
74	                sb.append(String.format("%02X", digest[i]));
75	            }
76	            return sb.toString();
77	        }
78	        catch (NoSuchAlgorithmException ex) {
79	            throw new IllegalStateException("SHA-256 not available", ex);
80	        }
81	    }
82	
83	    /** Lower-case and collapse runs of whitespace so comparison is case- and whitespace-insensitive. */
84	    private static String normalizeName(String value) {
85	        if (value == null) {
86	            return "";
87	        }
88	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
89	    }
90	}
