10	/**
11	 * Runs after {@link NormalizeOwnerAddress} on {@code POST /api/owners}, reading the published body:
12	 * rejects a request that is missing or blank in any of firstName, lastName, address, city or
13	 * telephone, listing every offending field. Because the address has already been normalized, an
14	 * address that is blank after normalization is reported here as a missing field.
15	 */
16	public class RequireOwnerFields {
17	
18	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
19	        List<String> missing = new ArrayList<>();
20	        require(missing, "firstName", request.getFirstName());
21	        require(missing, "lastName", request.getLastName());
22	        require(missing, "address", request.getAddress());
23	        require(missing, "city", request.getCity());
24	        require(missing, "telephone", request.getTelephone());
25	        if (!missing.isEmpty()) {
26	            throw new MissingOwnerFieldsException(missing);
27	        }
28	    }
29	
30	    private static void require(List<String> missing, String field, String value) {
31	        if (value == null || value.isBlank()) {
32	            missing.add(field);
33	        }
34	    }
35	}
